import java.io.*
import java.util.*

var N: Long = 1

fun mul(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
    val n = 6
    val c = Array(n) { LongArray(n) }
    for (i in 0 until n) {
        for (k in 0 until n) {
            if (a[i][k] == 0L) continue
            val aik = a[i][k]
            for (j in 0 until n) {
                c[i][j] = (c[i][j] + aik * b[k][j]) % N
            }
        }
    }
    return c
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val n = st.nextToken().toLong()
    val sx = st.nextToken().toLong()
    val sy = st.nextToken().toLong()
    val dx = st.nextToken().toLong()
    val dy = st.nextToken().toLong()
    var t = st.nextToken().toLong()
    N = n

    var m = arrayOf(
        longArrayOf(2, 1, 1, 0, 1, 2),
        longArrayOf(1, 2, 0, 1, 1, 2),
        longArrayOf(1, 1, 1, 0, 1, 2),
        longArrayOf(1, 1, 0, 1, 1, 2),
        longArrayOf(0, 0, 0, 0, 1, 1),
        longArrayOf(0, 0, 0, 0, 0, 1)
    )
    for (i in 0 until 6) for (j in 0 until 6) m[i][j] %= N

    var res = Array(6) { i -> LongArray(6) { j -> if (i == j) 1L % N else 0L } }

    while (t > 0) {
        if (t and 1L == 1L) res = mul(res, m)
        m = mul(m, m)
        t = t shr 1
    }

    val v = longArrayOf(
        (sx - 1) % n,
        (sy - 1) % n,
        ((dx % n) + n) % n,
        ((dy % n) + n) % n,
        0L,
        1L % n
    )

    val out = LongArray(6)
    for (i in 0 until 6) {
        var s = 0L
        for (j in 0 until 6) {
            s = (s + res[i][j] * v[j]) % N
        }
        out[i] = s
    }

    println("${out[0] + 1} ${out[1] + 1}")
}
